void rf_init (void)
{
  rf_res_update = os_res_create () ;

  bitfield_wr(rf_data.icon.bit , ICON_LOCK     , (RF_ICON_COUNT - 1), FALSE );

  rf_data.sound = NO_SOUND ;

  rftd2_init () ; 	
}

